// The compiled-in web/ files, generated by embed.cmake (control/ui/CMakeLists.txt).
#pragma once

#include <cstddef>

namespace tdr::cpui::detail {

struct EmbeddedFile {
    const char* path;           // relative to control/ui/web, e.g. "pages/jobs.js"
    const unsigned char* data;
    std::size_t size;
};

extern const EmbeddedFile kEmbedded[];  // kEmbeddedCount entries, then a null sentinel
extern const std::size_t kEmbeddedCount;

}  // namespace tdr::cpui::detail
